//   Course Clips/ C - Castle/ Outside Castle/C-O Back GFX / layer 'Layer 2' / frame 3
void frame_2949_1(Activation& scope) {
    stop();
    scope["bnum"] = random(30) + 30;
    scope["bcount"] = 0;
    _root["warpframe"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        //
        //Bird Chirp Code
        scope["bcount"]++;
        if (scope["bcount"] > scope["bnum"]) {
            _root["Mariosound"] = new_(Sound, scope.self);
            scope["btype"] = random(6) + 1;
            _root["Mariosound"]["attachSound"]("Birdy" + scope["btype"]);
            _root["Mariosound"]["start"](0, 1);
            _root["Mariosound"]["setVolume"](Math["round"](_root["MarioVolume"] / 1.5));
            scope["bcount"] = 0;

            scope["bnum"] = random(50) + 10;
        }
        //
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope.self["warp2"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 2;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            if (scope["warpnum"] == 2) {
                _root["attachMovie"]("righttransition", "righttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["RestartFludd"]();
                _root["BossCheckpoint"] = false;
                _root["changecourse"]("lefttransition2", "9-07", 0, 0, 0, 0, true);
            }
            if (scope["warpnum"] == 2) {
                //_root.changecourse("righttransition2", "8-E1-1", 0, 0, 0, 0);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
}

