//   Course Clips/ C - Castle/ Outside Castle/Castle Back GFX / layer 'Layer 4' / frame 3
void frame_2406_1(Activation& scope) {
    stop();
    _root["warpframe"] = false;
    scope["bnum"] = random(30) + 30;
    scope["bcount"] = 0;
    scope["btype"] = random(6) + 1;
    //
    scope.self["createEmptyMovieClip"]("birdsound", _root["getNextHighestDepth"]());
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        //
        //
        //trace("Cam : "+_root["Cam"+t+"change"])
        //
        scope["color"] += Math["round"](((_root["TotalStars"] * 1.5) + 25) - scope["color"]) / 7;
        if (_root["CheatCastleRestore"] == true) {
            scope["color"] = 100;
        }
        //color = Math.max(color, 0);
        //color = Math.min(color, 100);
        if (scope["color"] > 100) {
            scope["oldcolor"] = scope["color"];
            scope["color"] += Math["abs"](100 - scope["color"]) * 2.5;
        }
        scope["color2"] = Math["abs"](100 - scope["color"]);
        // color = percent of stars obained
        // color 2  = percent of stars not yet obtained
        scope["colorTrans"] = obj({{"ra", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"rb", 0}, {"ga", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"gb", 0}, {"ba", (scope["color"] * 0.5) + 50 - (scope["color2"] / 3)}, {"bb", 0}, {"aa", 100}, {"ab", 0}});
        scope["myColor"]["setTransform"](scope["colorTrans"]);
        if (scope["color"] > 100) {
            scope["color"] = scope["oldcolor"];
        }
        //
        //Bird Chirp Code
        if (_root["TotalStars"] > 20) {
            scope["birdvolume"] = 1;
            //
            scope["bcount"]++;
            if (scope["bcount"] > scope["bnum"]) {
                scope["birdsound"] = new_(Sound, scope.self);
                scope["birdsound"]["attachSound"]("Birdy" + scope["btype"]);
                scope["birdsound"]["start"](0, 1);
                scope["birdsound"]["setVolume"](Math["round"](_root["MarioVolume"] / 2) * scope["birdvolume"]);
                scope["bcount"] = 0;
                scope["btype"] = random(6) + 1;
                scope["bnum"] = random(50) + (73 - _root["TotalStars"]);
            }
        }
        //
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"]) && _root["Star"][39] == true) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        // && _root.Course.Char.yspeed<=0 && _root.TotalStars>=63
        if (scope.self["warp2"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 2;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            if (scope["warpnum"] == 2) {
                _root["attachMovie"]("righttransition", "righttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["changecourse"]("lefttransition2", "8-E1-2-2", 964, -783, 964, -783, true);
            }
            if (scope["warpnum"] == 2) {
                _root["Fluddpow"] = "";
                //_root.StopBGsong();
                _root["Restartcoins"]();
                _root["changecourse"]("righttransition2", "K-1", 0, 0, 0, 0, true);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
}

