//   Course Clips/ C - Castle/C-4HBackGFX / layer 'Layer 4' / frame 3
void frame_3105_0(Activation& scope) {
    _root["Starnamenum"] = 0;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope.self["warp2"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 2;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            if (scope["warpnum"] == 2) {
                if (scope["playedsound"] == false) {
                    _root["PaintingSound"]();
                }
                scope["playedsound"] = true;
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                //_root.StopBGsong();
                //_root.Playinglevel = ""
                _root["changecourse"]("lefttransition2", "C-1", 700, -250, 700, -250);
            }
            if (scope["warpnum"] == 2) {
                //_root.StopBGsong();
                _root["Fluddpow"] = "";
                _root["Restartcoins"]();
                //_root.Playinglevel = "";
                _root["changecourse"]("lefttransition2", "9-03", -50, -80, -50, -80, true);
            }
        }
        return undefined;
    });
}

