void frame_2539_0(Activation& scope) {
    scope["heightlevel"] = 0;
    _root["AreaTextClipF"]("Inside the Castle:" + scope["newline"] + "<i>Main Hall</i>", 1);
    scope["count"] = 0;
    _root["warpframe"] = false;
    _root["Starnamenum"] = 0;
    //  _root.TotalStars<=0 && _root.Star[39] == false
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (_root["Course"]["Char"]["_y"] - scope["_y"] > -34) {
            scope["heightlevel"] = 0;
        }
        if ((_root["Course"]["Char"]["_y"] - scope["_y"] < -57 || (_root["Course"]["Char"]["_y"] - scope["_y"] < -30 && _root["Course"]["Char"]["air"] == false)) && scope["heightlevel"] < 1) {
            scope["heightlevel"] = 1;
        }
        if ((_root["Course"]["Char"]["_y"] - scope["_y"] < -82 || (_root["Course"]["Char"]["_y"] - scope["_y"] < -55 && _root["Course"]["Char"]["air"] == false)) && scope["heightlevel"] < 2) {
            scope["heightlevel"] = 2;
        }
        //
        if (scope["heightlevel"] == 2 && _root["Course"]["Char"]["_y"] - scope["_y"] > -50) {
            scope["heightlevel"] = 1;
        }
        //
        gotoAndStop(scope["heightlevel"] + 2);
        //
        _root["Stats"]["screenfilter"]["_alpha"] = Math["round"]((64 - _root["TotalStars"]) * 0.25);
        //
        //
        //
        //
        //
        //
        if (scope["count"]++ > 4) {
            if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
                _root["Course"]["Char"]["attack"] = true;
                _root["Course"]["Char"]["xspeed"] = 0;
                _root["Course"]["Char"]["yspeed"] = 0;
                _root["Course"]["Char"]["attackFrame"] = "none";
                scope["warp"] = true;
                scope["warpnum"] = 1;
            }
            if (scope.self["warp2"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
                _root["Course"]["Char"]["attack"] = true;
                _root["Course"]["Char"]["xspeed"] = 0;
                _root["Course"]["Char"]["yspeed"] = 0;
                _root["Course"]["Char"]["attackFrame"] = "none";
                scope["warp"] = true;
                scope["warpnum"] = 2;
            }
            if (scope["warp"] == true && _root["warpframe"] == false) {
                if (scope["warpnum"] == 1) {
                    _root["attachMovie"]("righttransition", "righttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
                }
                if (scope["warpnum"] == 2) {
                    _root["attachMovie"]("uptransition", "uptransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
                }
            }
            if (_root["warpframe"] == true) {
                if (scope["warpnum"] == 1) {
                    //_root.StopBGsong();
                    //_root.Playinglevel = ""
                    _root["changecourse"]("righttransition2", "C-4H", 160, -170, 160, -170);
                }
                if (scope["warpnum"] == 2) {
                    //_root.StopBGsong();
                    //_root.Playinglevel = ""
                    _root["changecourse"]("uptransition2", "C-13", 950, -50, 950, -50);
                }
            }
        }
        return undefined;
    });
    //
}

